<div class="page-title"><div><em>ADMINISTRATION</em><h1>My profile</h1><p>Manage your administrator contact details and password.</p></div><a class="outline" href="<?=site_url('admin/logout')?>">⇥ Sign out</a></div>
<div class="grid admin-profile-grid"><section class="panel settings-form"><h2>Profile information</h2><p>Keep the email address used for administrator alerts up to date.</p><?=form_open('admin/profile')?><div class="profile-row"><span class="avatar big"><?=initials(($profile['first_name']??'').' '.($profile['last_name']??''))?></span><div><b><?=html_escape(($profile['first_name']??'').' '.($profile['last_name']??''))?></b><small>Administrator · <?=html_escape($profile['username']??'')?></small></div></div><div class="form-grid"><div><label>First name</label><input name="first_name" value="<?=html_escape($profile['first_name']??'')?>" required maxlength="80"></div><div><label>Last name</label><input name="last_name" value="<?=html_escape($profile['last_name']??'')?>" required maxlength="80"></div></div><label>Username</label><input value="<?=html_escape($profile['username']??'')?>" disabled><small class="field-hint">Your username is used to sign in and cannot be changed here.</small><label>Email address</label><input name="email" type="email" value="<?=html_escape($profile['email']??'')?>" required maxlength="190"><button class="btn">Save profile</button></form></section><section class="panel settings-form"><h2>Change password</h2><p>Use a strong password to protect administrator access.</p><?=form_open('admin/profile/password')?><label>Current password</label><input name="current_password" type="password" required autocomplete="current-password"><label>New password</label><input name="new_password" type="password" required minlength="8" autocomplete="new-password"><label>Confirm new password</label><input name="confirm_new" type="password" required minlength="8" autocomplete="new-password"><button class="btn">Update password</button></form><div class="security-note"><span>✓ <b>Secure administrator session</b><br>Last login: <?=html_escape($profile['last_login_at']??'Never')?> · IP <?=html_escape($profile['last_login_ip']??'—')?></span></div></section></div>
